-- Sample data: 3 coaches, 6 members (+ 4 of their kids), realistic session
-- history per coach/member pair (multiple sessions at different times,
-- cancelled sessions, a pending cancellation, pending/rejected join
-- requests) so the app has something to click around on locally.
--
-- Every seeded account shares the same password: password123

-- ─── COACHES ─────────────────────────────────────────────────────────────────



-- give the new coaches the global drill library, same as register_coach() does
SELECT c.user_id, d.drill_id
FROM coaches c CROSS JOIN drills d
WHERE c.user_id IN (
    '10000000-0000-0000-0000-000000000001',
    '10000000-0000-0000-0000-000000000002',
    '10000000-0000-0000-0000-000000000003'
) AND d.coach_id IS NULL;

